"        if ("POST".equals(method) && "/api/v1/iam/role-applications".equals(requestUri)) {
            return new RouteAuthorizationDecision(true, "iam:role-applications:write", null, null);
        }
        if ("POST".equals(method) && isSelfServiceCancelTicketUri(requestUri)) {
            return new RouteAuthorizationDecision(true, "governance:tickets:cancel", null, null);
        }
        Optional<PermissionEntity> matchedOpt = support.matchRoutePermission(method, requestUri);
        if (matchedOpt.isEmpty()) {
            return new RouteAuthorizationDecision(
                    false, null, ContractErrorCode.AUTH_FORBIDDEN.name(),
                    "No active RBAC permission mapping registered for " + method + " " + requestUri);
        }
        String code = matchedOpt.get().permissionCode();
        boolean permitted = isClearViewAs
                ? hasPermission(userId, null, false, code)
                : hasPermission(userId, effectiveViewAsRole, readOnlyOverlay, code);
        return permitted
                ? new RouteAuthorizationDecision(true, code, null, null)
                : new RouteAuthorizationDecision(false, code, ContractErrorCode.AUTH_FORBIDDEN.name(),
                        "Caller lacks required permission: " + code);
    }

    private static boolean isSelfServiceCancelTicketUri(String requestUri) {
        return requestUri.startsWith("/api/v1/tickets/") && requestUri.endsWith("/cancel");
    }"

